import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { rawQuery } from '@/lib/supabase/raw-query'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const PatchAccessSchema = z.object({
  show_on_booking_page:  z.boolean().optional(),
  can_view_clients:      z.boolean().optional(),
  can_edit_bookings:     z.boolean().optional(),
  can_message_clients:   z.boolean().optional(),
})

// Access columns added in migration 20260417230100_guest_artist_permissions.sql
// TODO: remove after `pnpm supabase gen types typescript --linked` includes these columns
interface EngagementAccess {
  show_on_booking_page: boolean
  can_view_clients: boolean
  can_edit_bookings: boolean
  can_message_clients: boolean
}

export async function GET(
  _req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const supabase = await createClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('role, studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  const { data: engagement, error } = await rawQuery<EngagementAccess>(supabase, 'guest_artist_engagements')
    .select('show_on_booking_page, can_view_clients, can_edit_bookings, can_message_clients')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()

  if (error || !engagement) {
    logger.warn({ engagementId: id, error }, 'guest_artist_access GET: engagement not found')
    return Response.json({ error: 'Not found' }, { status: 404 })
  }

  return Response.json({
    data: {
      show_on_booking_page: engagement.show_on_booking_page,
      can_view_clients:     engagement.can_view_clients,
      can_edit_bookings:    engagement.can_edit_bookings,
      can_message_clients:  engagement.can_message_clients,
    },
  })
}

export async function PATCH(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params

  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Rate limited' }, { status: 429 })

  const supabase = await createClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('role, studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  if (member.role !== 'owner' && member.role !== 'admin') {
    return Response.json({ error: 'Forbidden — only owners and admins can change access' }, { status: 403 })
  }

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return Response.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = PatchAccessSchema.safeParse(body)
  if (!parsed.success) {
    return Response.json({ error: parsed.error.flatten() }, { status: 422 })
  }

  const patch = parsed.data
  const dbPatch: Record<string, boolean> = {}
  if (patch.show_on_booking_page !== undefined) dbPatch['show_on_booking_page'] = patch.show_on_booking_page
  if (patch.can_view_clients     !== undefined) dbPatch['can_view_clients']     = patch.can_view_clients
  if (patch.can_edit_bookings    !== undefined) dbPatch['can_edit_bookings']    = patch.can_edit_bookings
  if (patch.can_message_clients  !== undefined) dbPatch['can_message_clients']  = patch.can_message_clients

  if (Object.keys(dbPatch).length === 0) {
    const { data: current } = await rawQuery<EngagementAccess>(supabase, 'guest_artist_engagements')
      .select('show_on_booking_page, can_view_clients, can_edit_bookings, can_message_clients')
      .eq('id', id)
      .eq('studio_id', member.studio_id)
      .single()

    return Response.json({
      data: {
        show_on_booking_page: current?.show_on_booking_page ?? false,
        can_view_clients:     current?.can_view_clients     ?? false,
        can_edit_bookings:    current?.can_edit_bookings    ?? false,
        can_message_clients:  current?.can_message_clients  ?? false,
      },
    })
  }

  const { data: updated, error } = await rawQuery<EngagementAccess>(supabase, 'guest_artist_engagements')
    .update(dbPatch)
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .select('show_on_booking_page, can_view_clients, can_edit_bookings, can_message_clients')
    .single()

  if (error || !updated) {
    logger.error({ engagementId: id, error }, 'guest_artist_access PATCH: update failed')
    return Response.json({ error: 'Update failed' }, { status: 500 })
  }

  return Response.json({
    data: {
      show_on_booking_page: updated.show_on_booking_page,
      can_view_clients:     updated.can_view_clients,
      can_edit_bookings:    updated.can_edit_bookings,
      can_message_clients:  updated.can_message_clients,
    },
  })
}

import { type NextRequest, NextResponse } from 'next/server'
import { createServiceRoleClient, getAuthenticatedUser } from '@/lib/supabase/server'
import { rawQuery } from '@/lib/supabase/raw-query'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import { z } from 'zod'

export const dynamic = 'force-dynamic'

const QuerySchema = z.object({
  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'date must be YYYY-MM-DD'),
})

/**
 * GET /api/admin/billing/day-events?date=2026-03-15
 * Returns billing events (subscription changes, payments) for a single day.
 * Platform admin only.
 */
export async function GET(req: NextRequest) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  if (!auth.user.is_platform_admin) return NextResponse.json({ error: 'forbidden' }, { status: 403 })

  const parsed = QuerySchema.safeParse({
    date: req.nextUrl.searchParams.get('date'),
  })
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 422 })
  }

  const { date } = parsed.data
  const dayStart = `${date}T00:00:00.000Z`
  const dayEnd   = `${date}T23:59:59.999Z`

  const supabase = createServiceRoleClient()

  // TODO: remove RawWebhookEvent + rawQuery once dodo_webhook_events is in generated types
  interface RawWebhookEvent {
    id: string
    event_type: string
    payload: Record<string, unknown> | null
    created_at: string
  }

  const { data: rawEvents, error } = await (rawQuery<RawWebhookEvent>(supabase, 'dodo_webhook_events')
    .select('id, event_type, payload, created_at')
    .gte('created_at', dayStart)
    .lte('created_at', dayEnd)
    .order('created_at', { ascending: true })
    .limit(200) as unknown as Promise<{ data: RawWebhookEvent[] | null; error: { message: string } | null }>)

  if (error) {
    logger.error({ err: error }, 'admin/billing/day-events: query failed')
    return NextResponse.json({ error: 'failed to load events' }, { status: 500 })
  }

  // Map webhook events to a friendly shape for the UI
  const mapped = (rawEvents ?? []).map(ev => {
    const payload = ev.payload ?? {}
    return {
      id: ev.id,
      type: ev.event_type ?? 'unknown',
      studio_name: (payload['studio_name'] as string | undefined) ?? 'Unknown studio',
      amount_cents: (payload['amount_cents'] as number | undefined) ?? (payload['amount'] as number | undefined) ?? 0,
      created_at: ev.created_at,
    }
  })

  return NextResponse.json({ date, events: mapped })
}

