/**
 * GET /api/payroll/artist-summaries/:id/comments
 * Returns all comments for an artist summary row.
 */
export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  const { id } = await params
  const supabase = await createClient()

  const summaryResult = await rawQuery<ArtistSummaryWithRun>(supabase, 'payroll_artist_summaries')
    .select('id, run:payroll_runs(studio_id)')
    .eq('id', id)
    .single()

  if (summaryResult.error || !summaryResult.data) {
    return NextResponse.json({ error: 'not found' }, { status: 404 })
  }

  const run = summaryResult.data.run
  if (!run || run.studio_id !== auth.studioId) {
    return NextResponse.json({ error: 'forbidden' }, { status: 403 })
  }

  const commentsResult = await (rawQuery<CommentRow>(supabase, 'payroll_run_comments')
    .select('id, body, created_at, author_id, author:studio_members(profile:profiles(full_name))')
    .eq('artist_summary_id', id)
    .order('created_at', { ascending: true }) as unknown as Promise<{ data: CommentRow[] | null; error: { message: string } | null }>)

  if (commentsResult.error) {
    logger.error({ err: commentsResult.error }, 'payroll/comments: GET failed')
    return NextResponse.json({ error: 'failed to load comments' }, { status: 500 })
  }

  const shaped = (commentsResult.data ?? []).map(c => {
    const authorArr = Array.isArray(c.author) ? c.author[0] : c.author
    return {
      id: c.id,
      body: c.body,
      created_at: c.created_at,
      author_id: c.author_id,
      author_name: authorArr?.full_name ?? 'Team member',
    }
  })

  return NextResponse.json({ data: shaped })
}

/**
 * POST /api/payroll/artist-summaries/:id/comments
 * Adds a comment to an artist summary.
 */
export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'unauthorized' }, { status: 401 })

  const { id } = await params

  const body = await req.json().catch(() => null)
  const parsed = PostSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 422 })
  }

  const supabase = await createClient()

  // Verify the summary belongs to this studio
  const summaryResult = await rawQuery<ArtistSummaryWithRun>(supabase, 'payroll_artist_summaries')
    .select('id, run:payroll_runs(studio_id)')
    .eq('id', id)
    .single()

  if (summaryResult.error || !summaryResult.data) {
    return NextResponse.json({ error: 'not found' }, { status: 404 })
  }

  const run = summaryResult.data.run
  if (!run || run.studio_id !== auth.studioId) {
    return NextResponse.json({ error: 'forbidden' }, { status: 403 })
  }

  const insertResult = await rawQuery<InsertedComment>(supabase, 'payroll_run_comments')
    .insert({
      artist_summary_id: id,
      author_id: auth.user.id,
      body: parsed.data.body,
    })
    .select('id, body, created_at, author_id')
    .single()

  if (insertResult.error || !insertResult.data) {
    logger.error({ err: insertResult.error }, 'payroll/comments: POST failed')
    return NextResponse.json({ error: 'failed to save comment' }, { status: 500 })
  }

  const comment = insertResult.data

  return NextResponse.json({
    data: {
      id: comment.id,
      body: comment.body,
      created_at: comment.created_at,
      author_id: comment.author_id,
      author_name: auth.user.full_name ?? 'Team member',
    },
  }, { status: 201 })
}

/**
 * GET /api/payroll/tax-forms/[id] — fetch tax form detail with signed PDF URL.
 * PDF URL is a signed Supabase Storage URL with 5-minute expiry (security req §7.2).
 */
import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { rawQuery } from '@/lib/supabase/raw-query'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'

// TODO: remove after `pnpm supabase gen types typescript --linked` includes artist_tax_info
interface ArtistTaxInfoRow {
  id: string
  tin_type: string | null
  tax_year: number | null
  status: string | null
  pdf_storage_path: string | null
  artist_id: string
  ssn_last4: string | null
}

interface ArtistMemberRow {
  profile: { full_name: string | null } | { full_name: string | null }[] | null
}

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return Response.json({ error: 'Rate limited' }, { status: 429 })

  const supabase = await createClient()
  const { data: { user } } = await supabase.auth.getUser()
  if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No membership' }, { status: 403 })

  // Security §7.1: gated to Owner/Admin
  if (!['owner', 'admin'].includes(member.role)) {
    return Response.json({ error: 'Forbidden — only owners and admins can view tax forms' }, { status: 403 })
  }

  const { data: form, error } = await rawQuery<ArtistTaxInfoRow>(supabase, 'artist_tax_info')
    .select('id, tin_type, tax_year, status, pdf_storage_path, artist_id, ssn_last4')
    .eq('id', id)
    .eq('studio_id', member.studio_id)
    .single()

  if (error || !form) {
    logger.warn({ formId: id, error }, 'tax form not found')
    return Response.json({ error: 'Not found' }, { status: 404 })
  }

  // Fetch artist name via studio_members -> profiles join
  const { data: artistMember } = await rawQuery<ArtistMemberRow>(supabase, 'studio_members')
    .select('profile:profiles(full_name)')
    .eq('id', form.artist_id)
    .single()

  const artistName = (() => {
    const p = artistMember?.profile
    if (!p) return 'Unknown artist'
    if (Array.isArray(p)) return p[0]?.full_name ?? 'Unknown artist'
    return p.full_name ?? 'Unknown artist'
  })()

  // Generate signed URL with 5-minute expiry (security §7.2)
  let signedPdfUrl: string | null = null
  if (form.pdf_storage_path) {
    const { data: signed } = await supabase
      .storage
      .from('tax-forms')
      .createSignedUrl(form.pdf_storage_path, 300) // 5 min
    signedPdfUrl = signed?.signedUrl ?? null
  }

  return Response.json({
    data: {
      id: form.id,
      form_type: form.tin_type === 'ssn' ? 'W-9' : '1099-NEC',
      tax_year: form.tax_year ?? new Date().getFullYear(),
      status: form.status,
      artist_name: artistName,
      ssn_last4: form.ssn_last4 ?? null,
      w9_status: null,
      signed_pdf_url: signedPdfUrl,
    },
  })
}

