────────────────────────────────────────────────────────── */
--chart-1: oklch(0.65 0.12 250);   /* muted blue — Solo plan */
--chart-2: oklch(0.65 0.12 180);   /* teal — Studio plan */
--chart-3: oklch(0.55 0.18 280);   /* primary purple — Pro plan */
--chart-4: oklch(0.70 0.15 60);    /* amber — Enterprise plan */
--chart-5: oklch(0.60 0.15 30);    /* orange — misc / 5th series */

