'use client'

import { cn } from '@/lib/utils'
import { Check } from 'lucide-react'

interface WizardStep {
  label: string
}

interface WizardStepperProps {
  steps: WizardStep[]
  currentStep: number
  className?: string
}

/**
 * WizardStepper — horizontal step indicator for multi-step forms.
 *
 * States:
 *   - Completed (< currentStep): filled primary circle + check icon + primary connector
 *   - Current (= currentStep): ring + primary/30 fill circle + primary connector to left
 *   - Upcoming (> currentStep): muted circle + muted connector
 */
export function WizardStepper({ steps, currentStep, className }: WizardStepperProps) {
  return (
    <div
      className={cn('flex items-center w-full max-w-[560px] mx-auto mb-8', className)}
      role="list"
      aria-label="Progress"
    >
      {steps.map((step, index) => {
        const isCompleted = index < currentStep
        const isCurrent   = index === currentStep
        const isUpcoming  = index > currentStep
        const isLast      = index === steps.length - 1

        return (
          <div
            key={step.label}
            className={cn('flex items-center', isLast ? 'shrink-0' : 'flex-1')}
            role="listitem"
            aria-current={isCurrent ? 'step' : undefined}
          >
            {/* Step node */}
            <div className="flex flex-col items-center gap-1">
              <div
                className={cn(
                  'flex h-7 w-7 items-center justify-center rounded-full transition-all duration-[180ms]',
                  isCompleted && 'bg-primary',
                  isCurrent  && 'ring-2 ring-primary ring-offset-2 ring-offset-background bg-primary/20',
                  isUpcoming && 'bg-muted',
                )}
                aria-label={`Step ${index + 1}: ${step.label}${isCompleted ? ' (completed)' : isCurrent ? ' (current)' : ''}`}
              >
                {isCompleted ? (
                  <Check className="size-3.5 text-primary-foreground" aria-hidden="true" />
                ) : (
                  <span
                    className={cn(
                      'text-[11px] font-semibold tabular-nums',
                      isCurrent  ? 'text-primary'           : 'text-muted-foreground',
                    )}
                  >
                    {index + 1}
                  </span>
                )}
              </div>
              <span
                className={cn(
                  'text-[10px] font-medium whitespace-nowrap',
                  isCurrent  ? 'text-foreground'       : 'text-muted-foreground',
                )}
              >
                {step.label}
              </span>
            </div>

            {/* Connector line (not shown after last step) */}
            {!isLast && (
              <div
                className={cn(
                  'flex-1 h-[2px] mx-2 mb-4 rounded-full transition-colors duration-[180ms]',
                  isCompleted ? 'bg-primary' : 'bg-border',
                )}
                aria-hidden="true"
              />
            )}
          </div>
        )
      })}
    </div>
  )
}

'use client'

import { useState, useRef } from 'react'
import { FileSpreadsheet, CheckCircle2, AlertTriangle, XCircle, Upload, ChevronLeft } from 'lucide-react'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { cn } from '@/lib/utils'
import { toast } from 'sonner'

interface BatchImportSheetProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onImportComplete?: () => void
}

/** CSV row after parsing */
interface ParsedRow {
  index: number
  brand: string
  ink_name: string
  batch_number: string
  lot_number: string
  manufacturer: string
  country: string
  reach_status: string
  expiry_date: string
  notes: string
  /** Validation result */
  status: 'valid' | 'warning' | 'error'
  statusMessage: string | null
}

type Step = 'upload' | 'preview' | 'result'

const TEMPLATE_HEADERS =
  'brand,ink_name,batch_number,lot_number,manufacturer,country,reach_status,expiry_date,notes'

const VALID_REACH_STATUSES = ['compliant', 'restricted', 'non_compliant', 'unknown']

function validateRow(row: Omit<ParsedRow, 'status' | 'statusMessage' | 'index'>, index: number): ParsedRow {
  if (!row.brand || !row.ink_name) {
    return { ...row, index, status: 'error', statusMessage: 'Brand and ink name are required' }
  }
  if (row.reach_status && !VALID_REACH_STATUSES.includes(row.reach_status.toLowerCase())) {
    return { ...row, index, status: 'warning', statusMessage: `Unknown REACH status: ${row.reach_status}` }
  }
  if (row.expiry_date && isNaN(Date.parse(row.expiry_date))) {
    return { ...row, index, status: 'error', statusMessage: 'Invalid expiry date — use YYYY-MM-DD' }
  }
  return { ...row, index, status: 'valid', statusMessage: null }
}

function parseCsv(text: string): ParsedRow[] {
  const lines = text.trim().split('\n')
  if (lines.length < 2) return []

  // Skip header line
  return lines.slice(1).map((line, idx) => {
    const cols = line.split(',').map((c) => c.trim().replace(/^"|"$/g, ''))
    const row = {
      brand:        cols[0] ?? '',
      ink_name:     cols[1] ?? '',
      batch_number: cols[2] ?? '',
      lot_number:   cols[3] ?? '',
      manufacturer: cols[4] ?? '',
      country:      cols[5] ?? '',
      reach_status: cols[6] ?? '',
      expiry_date:  cols[7] ?? '',
      notes:        cols[8] ?? '',
    }
    return validateRow(row, idx + 2) // +2 = 1-based + header
  })
}

function downloadTemplate() {
  const blob = new Blob([TEMPLATE_HEADERS + '\n'], { type: 'text/csv' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = 'inkos-ink-registry-template.csv'
  a.click()
  URL.revokeObjectURL(url)
}

export function BatchImportSheet({
  open,
  onOpenChange,
  onImportComplete,
}: BatchImportSheetProps) {
  const [step, setStep] = useState<Step>('upload')
  const [rows, setRows] = useState<ParsedRow[]>([])
  const [importedCount, setImportedCount] = useState(0)
  const [isDragging, setIsDragging] = useState(false)
  const [isImporting, setIsImporting] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)

  const validRows   = rows.filter((r) => r.status === 'valid')
  const warningRows = rows.filter((r) => r.status === 'warning')
  const errorRows   = rows.filter((r) => r.status === 'error')

  function handleFile(file: File) {
    if (!file.name.endsWith('.csv')) {
      toast.error('Please upload a CSV file')
      return
    }
    if (file.size > 5 * 1024 * 1024) {
      toast.error('File must be under 5MB')
      return
    }
    const reader = new FileReader()
    reader.onload = (e) => {
      const text = e.target?.result
      if (typeof text !== 'string') return
      const parsed = parseCsv(text)
      if (parsed.length === 0) {
        toast.error('No rows found in CSV. Make sure the file has a header row and data rows.')
        return
      }
      setRows(parsed)
      setStep('preview')
    }
    reader.readAsText(file)
  }

  function handleDrop(e: React.DragEvent<HTMLDivElement>) {
    e.preventDefault()
    setIsDragging(false)
    const file = e.dataTransfer.files[0]
    if (file) handleFile(file)
  }

  async function handleImport() {
    setIsImporting(true)
    try {
      const payload = validRows.map((r) => ({
        ink_brand:        r.brand,
        ink_product_code: r.ink_name,
        batch_number:     r.batch_number || null,
        reach_compliant:  r.reach_status.toLowerCase() === 'compliant',
        expiry_date:      r.expiry_date || null,
        notes:            r.notes || null,
      }))

      const res = await fetch('/api/reach/registry/batch', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ inks: payload }),
      })

      if (!res.ok) {
        const body = await res.json().catch(() => ({}))
        toast.error((body as { error?: string }).error ?? 'Import failed')
        return
      }

      const result = await res.json() as { imported: number }
      setImportedCount(result.imported ?? validRows.length)
      setStep('result')
    } catch {
      toast.error('Import failed. Please try again.')
    } finally {
      setIsImporting(false)
    }
  }

  function handleClose() {
    setStep('upload')
    setRows([])
    setImportedCount(0)
    onOpenChange(false)
  }

  function handleViewRegistry() {
    onImportComplete?.()
    handleClose()
  }

  return (
    <Sheet open={open} onOpenChange={(v) => { if (!v) handleClose() }}>
      <SheetContent className="w-[560px] flex flex-col gap-0 p-0">
        <SheetHeader className="px-6 py-4 border-b border-border/60">
          <SheetTitle>Import inks from CSV</SheetTitle>
          <SheetDescription>
            Upload a CSV file to bulk-import inks into your REACH registry.
          </SheetDescription>
        </SheetHeader>

        <div className="flex-1 overflow-y-auto px-6 py-5">

          {/* ── Step 1: Upload ── */}
          {step === 'upload' && (
            <div className="space-y-4">
              {/* Drop zone */}
              <div
                role="button"
                tabIndex={0}
                aria-label="Upload CSV file — click or drag and drop"
                className={cn(
                  'flex flex-col items-center justify-center gap-3 rounded-xl border-2 border-dashed p-10 cursor-pointer transition-colors duration-[120ms]',
                  isDragging
                    ? 'border-primary/60 bg-primary/5'
                    : 'border-border/60 hover:border-primary/40 hover:bg-muted/30',
                )}
                onDragOver={(e) => { e.preventDefault(); setIsDragging(true) }}
                onDragLeave={() => setIsDragging(false)}
                onDrop={handleDrop}
                onClick={() => fileInputRef.current?.click()}
                onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') fileInputRef.current?.click() }}
              >
                <div className="rounded-xl bg-muted/60 p-3">
                  <FileSpreadsheet className="size-8 text-muted-foreground/60" aria-hidden="true" />
                </div>
                <div className="text-center">
                  <p className="text-[14px] font-medium text-foreground">
                    Drop CSV file here or click to browse
                  </p>
                  <p className="text-[12px] text-muted-foreground mt-0.5">.csv up to 5MB</p>
                </div>
                <input
                  ref={fileInputRef}
                  type="file"
                  accept=".csv"
                  className="sr-only"
                  onChange={(e) => {
                    const file = e.target.files?.[0]
                    if (file) handleFile(file)
                    e.target.value = ''
                  }}
                  aria-label="File upload input"
                />
              </div>

              {/* Template download */}
              <Button
                variant="ghost"
                size="sm"
                className="w-full"
                onClick={downloadTemplate}
                type="button"
              >
                <Upload className="size-4 mr-2" aria-hidden="true" />
                Download template CSV
              </Button>

              <div className="rounded-lg bg-muted/40 p-4">
                <p className="text-[12px] font-medium text-foreground mb-1">Required columns</p>
                <p className="text-[11px] font-mono text-muted-foreground break-all">
                  brand, ink_name, batch_number, lot_number, manufacturer, country, reach_status, expiry_date, notes
                </p>
              </div>
            </div>
          )}

          {/* ── Step 2: Preview ── */}
          {step === 'preview' && (
            <div className="space-y-4">
              <div className="flex items-center gap-3">
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => { setStep('upload'); setRows([]) }}
                  type="button"
                >
                  <ChevronLeft className="size-4 mr-1" aria-hidden="true" />
                  Back
                </Button>
                <p className="text-[13px] text-muted-foreground">
                  Parsed <span className="font-semibold text-foreground">{rows.length}</span> rows. Review before importing.
                </p>
              </div>

              {/* Preview table */}
              <div className="rounded-xl border border-border/60 overflow-hidden">
                <div className="max-h-[300px] overflow-y-auto">
                  <table className="w-full text-[12px]">
                    <thead className="bg-muted/40 sticky top-0">
                      <tr>
                        <th className="px-3 py-2 text-left font-medium text-muted-foreground">Brand</th>
                        <th className="px-3 py-2 text-left font-medium text-muted-foreground">Ink name</th>
                        <th className="px-3 py-2 text-left font-medium text-muted-foreground">Batch</th>
                        <th className="px-3 py-2 text-left font-medium text-muted-foreground">Status</th>
                        <th className="px-3 py-2 text-left font-medium text-muted-foreground">Expiry</th>
                        <th className="px-3 py-2 text-left font-medium text-muted-foreground">Validation</th>
                      </tr>
                    </thead>
                    <tbody>
                      {rows.map((row) => (
                        <tr key={row.index} className="border-t border-border/40 hover:bg-muted/20">
                          <td className="px-3 py-2 font-medium">{row.brand || <span className="text-muted-foreground/50 italic">—</span>}</td>
                          <td className="px-3 py-2">{row.ink_name || <span className="text-muted-foreground/50 italic">—</span>}</td>
                          <td className="px-3 py-2 font-mono">{row.batch_number || '—'}</td>
                          <td className="px-3 py-2">{row.reach_status || '—'}</td>
                          <td className="px-3 py-2">{row.expiry_date || '—'}</td>
                          <td className="px-3 py-2">
                            {row.status === 'valid' && (
                              <div className="flex items-center gap-1 text-green-700 dark:text-green-400">
                                <CheckCircle2 className="size-3.5" aria-hidden="true" />
                                <span>Valid</span>
                              </div>
                            )}
                            {row.status === 'warning' && (
                              <div
                                className="flex items-center gap-1 text-amber-700 dark:text-amber-400 cursor-help"
                                title={row.statusMessage ?? undefined}
                              >
                                <AlertTriangle className="size-3.5" aria-hidden="true" />
                                <span>Warning</span>
                              </div>
                            )}
                            {row.status === 'error' && (
                              <div
                                className="flex items-center gap-1 text-destructive cursor-help"
                                title={row.statusMessage ?? undefined}
                              >
                                <XCircle className="size-3.5" aria-hidden="true" />
                                <span>Error</span>
                              </div>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>

              {/* Summary */}
              <div className="flex items-center gap-3 text-[12px]">
                <Badge className="bg-green-500/15 text-green-700 dark:text-green-400 border-green-500/20">
                  {validRows.length} valid
                </Badge>
                {warningRows.length > 0 && (
                  <Badge className="bg-amber-500/15 text-amber-700 dark:text-amber-400 border-amber-500/20">
                    {warningRows.length} warnings
                  </Badge>
                )}
                {errorRows.length > 0 && (
                  <Badge variant="destructive">
                    {errorRows.length} errors
                  </Badge>
                )}
              </div>

              <Button
                className="w-full"
                disabled={validRows.length === 0 || isImporting}
                onClick={handleImport}
                type="button"
              >
                {isImporting ? 'Importing…' : `Import ${validRows.length} valid ${validRows.length === 1 ? 'row' : 'rows'}`}
              </Button>
            </div>
          )}

          {/* ── Step 3: Result ── */}
          {step === 'result' && (
            <div className="flex flex-col items-center justify-center gap-4 py-8 text-center">
              <CheckCircle2 className="size-12 text-green-500" aria-hidden="true" />
              <div>
                <p className="text-[16px] font-semibold">
                  {importedCount} {importedCount === 1 ? 'ink' : 'inks'} imported successfully
                </p>
                {warningRows.length > 0 && (
                  <p className="text-[13px] text-muted-foreground mt-1">
                    {warningRows.length} {warningRows.length === 1 ? 'row was' : 'rows were'} skipped due to warnings
                  </p>
                )}
              </div>
              <div className="flex flex-col gap-2 w-full max-w-[280px]">
                <Button variant="default" className="w-full" onClick={handleViewRegistry} type="button">
                  View registry
                </Button>
                <Button variant="outline" className="w-full" onClick={handleClose} type="button">
                  Close
                </Button>
              </div>
            </div>
          )}

        </div>
      </SheetContent>
    </Sheet>
  )
}

